import{_ as o,l as r,o as e,c as n,v as l,p,x as t,d as s,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"照明偏振控制","description":"","frontmatter":{"title":"照明偏振控制","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/illuminator-polarization.md","filePath":"litho/illuminator-polarization.md","lastUpdated":1789023840000}'),d={name:"litho/illuminator-polarization.md"};function m(T,a,c,A,u,_){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="照明偏振控制" tabindex="-1">照明偏振控制 <a class="header-anchor" href="#照明偏振控制" aria-label="Permalink to &quot;照明偏振控制&quot;">​</a></h1><div class="epigraph"><p>瞳面上的能量分布决定哪些级能进镜头；每个源点的琼斯矢量决定这些级在像面还干不干涉。切向偏振是给两束成像买 TE，不是又一张光瞳图。</p><footer>—— 据 Flagello 等对高 NA 矢量成像与偏振的讨论，以及 ASML 浸没照明器对偏振模式的公开表述</footer></div><p><a href="/litho/flexray-pupil">上一课</a>把光瞳从固定 DOE 扩成可编程灰度。缺口是：同一张偶极或花瓣，非偏振、线偏振、切向偏振在胶里的对比可以差一截。<a href="/litho/vector-imaging">矢量成像</a>已经说明 TE 干涉深、TM 交叉项变弱；本课只把这句话接到照明器上——控制的是源点偏振，不是再推一遍 \\(\\cos 2\\theta\\)。掩模课序从相移另起，本课不开始写 PSM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FlexRay 解决了「能量放在瞳面哪里」。高 \\(\\mathrm{NA}\\) 浸没下，放对位置仍可能买到 TM 为主的两束：电矢量沿各自 \\(\\mathbf{k}\\) 张开，暗区抬高，上一课辛辛苦苦排好的极等于白排。照明器因此要在瞳面像素上附偏振态：线偏振（常称 X/Y）、切向（方位/TE，电场沿圆周）、有时还有径向。</p><p>缺口因此是照明偏振作为 RET 旋钮，而不是重做胶内能量沉积的定义。没有这层，偶极层会把「极半径错了」和「TM 把对比吃了」缠在一起。</p><h3 id="切向不是「又一种-σ」" tabindex="-1">切向不是「又一种 σ」 <a class="header-anchor" href="#切向不是「又一种-σ」" aria-label="Permalink to &quot;切向不是「又一种 σ」&quot;">​</a></h3><p>切向偏振让每个离轴源点的电场大致垂直于半径方向。对沿 y 的密线配 x 向偶极时，两束接近 TE，交叉项大。非偏振是 TE 与 TM 的强度平均，密节距的 NILS 夹在中间。XY 偏振则按象限或按轴指定线偏振，实现比理想切向容易，对曼哈顿栅够用，对任意取向图形会露出接缝。</p><p><span class="marginnote">Flagello 把高 NA 成像写成矢量边值：对比度对偏振的敏感随孔径角上升。浸没 \\(\\mathrm{NA}=1.35\\) 后，照明器产品把偏振模式与 dipole / C-quad 绑在一起卖，不是光学论文里的可选附录。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>扫描机照明器在积分棒或偏振光学之后，给瞳面指定琼斯场。经典搭配：强偶极 + 切向（或与栅极垂直的线偏振）；C-quad 用 XY 一类分段线偏振，让 x 极服务 y 线、y 极服务 x 线。环形上切向仍可能，但孔类与多取向图形的窗口交要单独验，不能从栅极食谱抄。</p><p>标定：用偏振分析或专用标记看残余 TM、漏光与双折射。投影物镜镀膜的 s/p 差是二阶，主旋钮仍在照明侧。换偏振必须重做 OPC：TCC 变了，旧边碎片失效，与换光瞳同一纪律。</p><h3 id="自由光瞳上的偏振图" tabindex="-1">自由光瞳上的偏振图 <a class="header-anchor" href="#自由光瞳上的偏振图" aria-label="Permalink to &quot;自由光瞳上的偏振图&quot;">​</a></h3><p>可编程瞳可以给不同像素不同偏振，但硬件往往只能实现几种全局或分象限模式，而不是每个微镜任意琼斯。SMO 若输出「左上极要 TE、右下极要 TM」，要先问照明器是否做得到。本课不展开 SMO，只要求自由光瞳的可实现集合包含偏振，而不是只包含灰度。</p>',14)),(e(),p(h,null,{default:t(()=>[E(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUP%5B%22%E7%9E%B3%E9%9D%A2%E7%81%B0%E5%BA%A6%20%E4%B8%8A%E4%B8%80%E8%AF%BE%22%5D%20--%3E%20POL%5B%22%E6%BA%90%E7%82%B9%E7%90%BC%E6%96%AF%22%5D%0A%20%20POL%20--%3E%20TE%5B%22%E5%88%87%E5%90%91%20%2F%20TE%20%E4%B8%A4%E6%9D%9F%22%5D%0A%20%20POL%20--%3E%20UNP%5B%22%E9%9D%9E%E5%81%8F%E6%8C%AF%20%E5%B9%B3%E5%9D%87%22%5D%0A%20%20TE%20--%3E%20NILS%5B%22%E5%AF%86%E7%BA%BF%20NILS%20%E9%AB%98%22%5D%0A%20%20UNP%20--%3E%20NILS%0A%20%20POL%20--%3E%20OPC%5B%22OPC%20%2F%20TCC%20%E5%BF%85%E9%A1%BB%E9%87%8D%E7%AE%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个源点携带琼斯矢量，经掩模与投影后在像面做矢量叠加，再对源积分。切向的目标是让目标节距的那一对级以 TE 为主进入胶。TM 成分不会被偏振器魔法消掉：极张角一大、或图形取向一偏，残余 TM 仍在。矢量效应在最佳焦距就存在，偏振控制是避开最差组合，不是取消高 NA。</p><p>掩模开口本身是弱偏振器，厚铬栅会改 s/p 透过。那是掩模 3D 课的电磁边值。本课的物是「照明器出口的偏振」，假定薄掩模或已校准的 Jones 瞳。EUV 斜入射的偏振与多层膜反射率另账，不要把浸没切向食谱抄到 NXE。</p><p>与上一课的耦合：自由光瞳把能量摆到极上，切向再让这些极以 TE 为主。只优化灰度、不声明偏振，SMO 窗口会在浸没上虚高一截。Flagello 的敏感度曲线是这条耦合的实验背景，不是又一张瞳形分类。</p><p><span class="marginnote">偏振纯度不够时，宣传上的「TE 偶极」在晶圆上仍是部分退偏。匹配两台机器要把残余偏振纳入光瞳指纹，否则 CD 差会被误写成剂量或 \\(\\sigma\\) 误差。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲胶内驻波如何按 s/p 分层，也不把物镜应力双折射当成照明器功能。低 NA、松节距仍可用非偏振；切换判据是 \\(\\mathrm{NA}\\) 与目标密节距，不是机台品牌。切向偏振不修复套刻，也不替代浸没水层。</p><p>后课默认：凡写照明配方，除瞳形外必须声明偏振。只报「用了 FlexRay 偶极」而不报 TE/XY，后课的 \\(k_1\\) 窗口会乐观。</p><p><span class="marginnote">剂量时间仍可能变：偏振元件有损耗，瘦偶极再加偏振器，晶圆面光强再掉一截。窗口与 wph 的交点要一起看，本课不编产能表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可编程光瞳管能量落点；偏振管这些能量还干不干涉。</li><li>切向 / TE 服务目标取向的两束；XY 服务曼哈顿四极。</li><li>不重写矢量成像推导，只把 Flagello 的敏感接到照明器。</li><li>换偏振 = 换 TCC，OPC 必须重做。</li><li>掩模作为偏振器留给 M3D；EUV 另论。</li><li>出处：Flagello 等对高 NA 偏振成像；ASML 浸没照明偏振模式的公开表述。</li></ul>',11))])}const f=o(d,[["render",m]]);export{B as __pageData,f as default};
